# policy/naming_and_sku.rego — evaluated with Conftest against `terraform show -json plan.out`

package main

approved_skus := {"S0", "S1", "Standard"}

deny[msg] {
  resource := input.resource_changes[_]
  resource.type == "azurerm_cognitive_account"
  not approved_skus[resource.change.after.sku_name]
  msg := sprintf("SKU '%s' is not on the approved list for %s", [resource.change.after.sku_name, resource.address])
}

deny[msg] {
  resource := input.resource_changes[_]
  resource.type == "azurerm_cognitive_account"
  resource.change.after.public_network_access_enabled == true
  msg := sprintf("%s must disable public network access (private endpoint required)", [resource.address])
}

deny[msg] {
  resource := input.resource_changes[_]
  startswith(resource.type, "azurerm_")
  not regex.match("^[a-z]{2,4}-[a-z0-9-]+-(dev|test|prod)$", resource.change.after.name)
  msg := sprintf("%s does not follow naming convention <type>-<workload>-<env>", [resource.address])
}
